const PREFIX='note-studio-pro:'+self.registration.scope+':';
const CACHE_NAME=PREFIX+VERSION;
const entries=new Map(ASSETS.map(asset=>[new URL(asset.url,self.registration.scope).href,asset]));
const indexURL=new URL('index.html',self.registration.scope).href;
const assetRequest=url=>new Request(url,{cache:'reload',credentials:'same-origin',...(entries.get(url).integrity?{integrity:entries.get(url).integrity}:{})});
let refreshing=null;
async function cacheAll(){
  if(refreshing)return refreshing;
  refreshing=(async()=>{
    const cache=await caches.open(CACHE_NAME);
    const responses=await Promise.all([...entries.keys()].map(async url=>{
      try{
        const response=await fetch(assetRequest(url));
        if(!response.ok)throw Error('HTTP '+response.status);
        if(url===indexURL&&!(await response.clone().text()).includes('<meta name="note-studio-build" content="'+VERSION+'">'))throw Error('Editor page belongs to another build');
        return {url,response};
      }catch(error){throw Error('Offline file '+new URL(url).pathname+' failed: '+error.message);}
    }));
    for(const {url,response}of responses)await cache.put(url,response);
  })();
  try{await refreshing;}finally{refreshing=null;}
}
async function ready(){
  const cache=await caches.open(CACHE_NAME);
  return (await Promise.all([...entries.keys()].map(url=>cache.match(url)))).every(Boolean);
}
self.addEventListener('install',event=>{
  event.waitUntil(cacheAll().catch(async error=>{
    await caches.delete(CACHE_NAME);
    const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});
    for(const client of clients)if(client.url.startsWith(self.registration.scope))client.postMessage({type:'NOTE_STUDIO_CACHE_ERROR',message:error.message});
    throw error;
  }));
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    const keys=await caches.keys();
    await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE_NAME).map(key=>caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener('fetch',event=>{
  const request=event.request;
  if(request.method!=='GET')return;
  const url=new URL(request.url),scope=new URL(self.registration.scope);
  if(url.origin!==scope.origin)return;
  let canonical=new URL(url.pathname,url.origin).href;
  if(request.mode==='navigate'&&(url.pathname===scope.pathname||url.pathname===new URL(indexURL).pathname))canonical=indexURL;
  if(!entries.has(canonical))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE_NAME);
    const cached=await cache.match(canonical);
    if(cached)return cached;
    try{
      const response=await fetch(assetRequest(canonical));
      if(!response.ok)throw Error('Asset unavailable');
      if(canonical===indexURL&&!(await response.clone().text()).includes('<meta name="note-studio-build" content="'+VERSION+'">'))throw Error('Editor page belongs to another build');
      await cache.put(canonical,response.clone());
      return response;
    }catch{return new Response('Offline app files are unavailable. Reopen Note Studio Pro while online to complete setup.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});}
  })());
});
self.addEventListener('message',event=>{
  if(!event.source?.url?.startsWith(self.registration.scope))return;
  const reply=value=>event.ports?.[0]?.postMessage(value);
  if(event.data?.type==='GET_STATUS')event.waitUntil(ready().then(offlineReady=>reply({version:VERSION,offlineReady})));
  else if(event.data?.type==='REFRESH_CACHE')event.waitUntil(cacheAll().then(()=>reply({offlineReady:true})).catch(()=>reply({offlineReady:false})));
  else if(event.data?.type==='ACTIVATE_UPDATE')event.waitUntil((async()=>{
    const windows=(await self.clients.matchAll({type:'window',includeUncontrolled:true})).filter(client=>client.url.startsWith(self.registration.scope));
    if(windows.length>1){reply({multipleWindows:true});return;}
    reply({activating:true});await self.skipWaiting();
  })());
});
